import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return
    A = list(map(int, input_data))

    from itertools import permutations

    min_cost = float('inf')

    for p in permutations(A):
        cost = 0
        # First task is free
        # Then cost is sum of absolute differences between consecutive tasks
        for i in range(1, 3):
            cost += abs(p[i] - p[i-1])
        if cost < min_cost:
            min_cost = cost

    print(min_cost)

if __name__ == "__main__":
    solve()

